import java.time.Duration;

HttpClient client = HttpClient.newBuilder()
    .connectTimeout(Duration.ofSeconds(10))
    .build();

String json = "{\"name\":\"Product Launch Landing Page\",\"qrType\":\"WEB\",\"displayId\":\"product-launch-2024\",\"qrRedirectUrl\":\"https://acmecorp.com/product-launch\",\"templateId\":\"qwrIYX8iLAuDHSBCiKZl\",\"baseUrl\":\"https://qr.qrtrac.com/\"}";

HttpRequest request = HttpRequest.newBuilder()
    .uri(URI.create("https://api.qrtrac.com/api/qrs-api"))
    .header("x-request-team-id", "<team_id>")
    .header("x-request-client-id", "<client_id>")
    .header("x-request-client-secret", "<client_secret>")
    .header("Content-Type", "application/json")
    .POST(HttpRequest.BodyPublishers.ofString(json))
    .build();

